code.TokenTimelock.release():
function release() public {
 require(uint64(block.timestamp) >= releaseTime);
 uint256 amount = token.balanceOf(this);
 require(amount > 0);
 token.safeTransfer(beneficiary, amount);
 }

code.TokenTimelock.TokenTimelock(ERC20Basic,a:
function TokenTimelock(ERC20Basic _token, address _beneficiary, uint64 _releaseTime) public {
 require(_releaseTime > uint64(block.timestamp));
 token = _token;
 beneficiary = _beneficiary;
 releaseTime = _releaseTime;
 }

code.SafeMath.add(uint256,uint256):
function add(uint256 a, uint256 b) internal pure returns (uint256) {
 uint256 c = a + b;
 require(c >= a);
 return c;
 }

code.SafeMath.sub(uint256,uint256):
function sub(uint256 a, uint256 b) internal pure returns (uint256) {
 require(b <= a);
 return a - b;
 }

code.SafeMath.mul(uint256,uint256):
function mul(uint256 a, uint256 b) internal pure returns (uint256) {
 uint256 c = a * b;
 require(a == 0 || c / a == b);
 return c;
 }

code.SafeMath.div(uint256,uint256):
